xhtml:body.xhtml:script:
//
  (function() {
    function size() {
      var w = window.innerWidth || 1920, h = window.innerHeight || 1080;
      var svg = document.querySelector('svg');
      var fo = document.querySelector('foreignObject');
      if (svg) { svg.setAttribute('width', w); svg.setAttribute('height', h); svg.setAttribute('viewBox', '0 0 ' + w + ' ' + h); }
      if (fo) { fo.setAttribute('width', w); fo.setAttribute('height', h); }
    }
    size();
    window.addEventListener('resize', size);

    (async () => {
      try {
        var fallbackCdn = 'https://fastly.jsdelivr.net/gh/deezlightlysaltednuts-bot/petezah-mirrors@main/';
        var host = (location && location.origin && location.origin !== 'null') ? location.origin : 'https://fastly.jsdelivr.net';
        var pathname = (location && location.pathname) ? location.pathname : '';
        var dir = pathname.substring(0, pathname.lastIndexOf('/') + 1);
        var baseCdn = (host.startsWith('http') && dir) ? (host + dir) : fallbackCdn;
        if (!baseCdn.endsWith('/')) baseCdn += '/';

        var res = await fetch(baseCdn + 'index.html?t=' + Date.now()).catch(function() {
          return fetch(fallbackCdn + 'index.html');
        });
        var html = await res.text();

        var rootCdn = fallbackCdn;
        var baseTag = '<base href="' + rootCdn + '">';
        if (html.includes('<head>')) {
          html = html.replace('<head>', '<head>' + baseTag);
        } else {
          html = baseTag + html;
        }
        html = html.replace(/(src|href)=["']\/?assets\//g, '$1="' + rootCdn + 'assets/');

        var frame = document.getElementById('fm');
        frame.srcdoc = html;
      } catch (err) {
        console.error('PeteZah Edge Loader Error:', err);
      }
    })();
  })();
//
